mapper.select:
SELECT session_id, user_id, username, title, msg_count, create_time, update_time
FROM agent_session WHERE user_id = #{userId}
ORDER BY update_time DESC
LIMIT #{limit}

SELECT msg_id, session_id, role, content, create_time FROM (
    SELECT msg_id, session_id, role, content, create_time
    FROM agent_message WHERE session_id = #{sessionId}
    ORDER BY msg_id DESC LIMIT #{limit}
) t ORDER BY msg_id ASC
